    vector<int> hash(n + 1, 0);
    for (int i = 0, x; i < n; ++i) {
        cin >> x;
        hash[x]++;
    }

    for (int i = 1; i < n; i++) {
        if (hash[i] > 2) {
            hash[i + 1] += hash[i] - 2;
            hash[i] = 2;
        }
    }

    for (int i = 1; i <= n; i++) {
        if (hash[i] % 2 == 1) {
            No;
            return;
        }
    }

    Yes;
}

